import "core-js/modules/es6.function.name";
import "core-js/modules/es6.string.link";
import "core-js/modules/es6.number.constructor";
import { attachSave, attachGetAttach, attachRemove, removeFile } from "@/api/system/devInBound";
import website from '@/config/website';
import { Base64 } from 'js-base64';
import { getToken } from '@/util/auth';
import { uploadFile1 } from "@/api/ictOperation/index";
export default {
  name: "ComputerRoomDetail",
  components: {},
  props: {
    fileList: {
      type: Array
    },
    serialNumber: {
      type: String
    },
    attachId: {
      type: Number
    },
    type: {
      type: String
    },
    columName: {
      type: String
    },
    detailId: {
      default: false
    },
    disabled: {
      type: Boolean,
      default: false
    },
    limit: {
      type: Number
    }
  },
  data: function data() {
    return {
      // fileList: [],
      showLoading: false,
      dialogVisible: false,
      dialogImageUrl: '',
      deviceData: {
        // businessKey: this.businessKey,
        // tableName: "hidden_problem_evidence",
        // columName: "file_url"
      },
      // 用户导入参数
      upload: {
        // 是否显示弹出层（用户导入）
        open: false,
        // 弹出层标题（用户导入）
        title: '',
        // 是否禁用上传
        isUploading: false,
        // 是否更新已经存在的用户数据
        updateSupport: 0,
        // 设置上传的请求头部
        headers: {
          Authorization: "Basic ".concat(Base64.encode("".concat(website.clientId, ":").concat(website.clientSecret))),
          'Idevelop-Auth': 'bearer ' + getToken()
        },
        // 上传的地址
        url: '/api/idevelop-resource/oss/endpoint/put-file',
        imageUrl: null
      },
      resObj: {}
    };
  },
  computed: {
    fileListNo: {
      get: function get() {
        return this.fileList;
      },
      set: function set(val) {
        this.$emit("update:fileList", val);
      }
    }
  },
  created: function created() {
    // this.getFiles()
  },
  mounted: function mounted() {},
  methods: {
    renderList: function renderList(files) {
      if (files.id) {
        var fileArray = new Array();
        var item = {
          id: files.id,
          name: files.fileName,
          url: files.filePath
        };
        fileArray.push(item);
        this.fileListNo = fileArray;
      } else {
        this.fileListNo = [];
      }
    },
    getFiles: function getFiles(file) {
      var _this = this;
      if (file) {
        this.renderList(file);
        return;
      }
      if (this.serialNumber) {
        this.showLoading = true;
        var params = {
          // attachId: this.attachId,
          storageId: this.serialNumber
        };
        attachGetAttach(params).then(function (response) {
          if (response.code === 200) {
            var files = response.data;
            if (files.length > 0) {
              _this.renderList(files[0]);
            }
          } else {
            _this.$message.error(response.msg);
          }
          _this.showLoading = false;
        });
      }
    },
    uploadFile2: function uploadFile2(params) {
      var file = params.file;
      var formData = new FormData();
      formData.append("file", file);
      uploadFile1(formData).then(function (res) {
        params.onSuccess(res);
      });
    },
    // 文件上传成功处理
    // eslint-disable-next-line no-unused-vars
    handleFileSuccess: function handleFileSuccess(response, file, fileList) {
      // console.log(909090, response)
      this.resObj = response.data;
      var orderFileType = 0;
      //工单上传文件类型 0 设备申请线下申请单附件 1 设备出库出库照片 2 设备投运旧设备照片
      if (this.type == '投运工单') {
        orderFileType = 1;
      } else if (this.type == '投运工单') {
        orderFileType = 2;
      }
      var params = {
        fileName: response.data.originalName || '',
        fileType: '',
        fileUrl: response.data.link || '',
        orderFileType: orderFileType,
        name: response.data.originalName || '',
        url: response.data.link || '',
        status: null
      };

      // console.log(11111, this.fileListNo)
      // fileList.push(params)

      this.$emit('setVal', params, fileList);
      this.dialogImageUrl = file.url;
    },
    // eslint-disable-next-line no-unused-vars
    myAttachSave: function myAttachSave(serialNumber, file) {
      var _this2 = this;
      if (!this.resObj.link) {
        return;
      }
      var params = {
        businessType: 'rk',
        fileName: this.resObj.originalName,
        filePath: this.resObj.link,
        filingNo: serialNumber
      };
      // if(this.serialNumber){
      attachSave(params).then(function (res) {
        _this2.resObj = {};
      });
      // }
    },
    handleRemove: function handleRemove(file, fileList) {
      var _this3 = this;
      // console.log(777, file)
      // 旧图片作为脏数据，不在需要删除
      // removeFile({ originalName: file.name }).then(res=>{  })
      //删除旧图片
      // this.fileListNo = []
      this.$emit('setVal', null, fileList);
      if (!file.id) {
        this.resObj = {};
        return;
      }
      var data = {
        ids: file.id
      };
      if (this.serialNumber) {
        attachRemove(data).then(function (response) {
          if (response.code === 200) {
            // this.fileListNo = []
          } else {
            _this3.$message.error(response.msg);
          }
        });
      }
      this.resObj = {};
    },
    handleExceed: function handleExceed() {
      // console.log(456456, this.fileListNo)
      this.$message.warning('图片上传数量已上限！');
    },
    // 文件上传中处理
    handleFileUploadProgress: function handleFileUploadProgress(event, file) {
      // this.upload.isUploading = true
    },
    handlePreview: function handlePreview(file) {
      this.dialogImageUrl = file.url;
      this.dialogVisible = true;
    },
    //上传之前操作(用于判断是否重名与格式限制)
    beforeUpload: function beforeUpload(file) {
      var acceptType = ['jpg', 'jpeg', 'png', 'PNG', 'bmp'];
      var extension = file.name.substring(file.name.lastIndexOf('.') + 1);
      if (-1 === acceptType.indexOf(extension)) {
        this.$message.warning('支持文件格式' + acceptType + '！');
        return false;
      }
      // if (file.size/1024 > 5 * 1024) {
      //   this.$message.warning("当前文件超过5M，请修改！");
      //   return false;
      // }
    }
  }
};
